/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'db.sqlite') }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  let output = '';
  const port = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.once('error', reject);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
  });
  const health = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(health.status, 200);
  assert.deepEqual(await health.json(), { status: '"'ok' });
  console.log('npm start and GET /health verified');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
